SELECT id, reading_ts, humidity, CORR(status_bits, pressure) OVER (PARTITION BY device_code) AS corr_status_bits_pressure, CORR(status_bits, pressure) OVER (PARTITION BY device_code) AS corr_status_bits_pressure_2, LAST_VALUE(temp_c) IGNORE NULLS OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_temp_c, AVG(temp_c) OVER (ORDER BY temp_c, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS temp_c_avg_3, CUME_DIST() OVER (PARTITION BY device_code ORDER BY humidity DESC) AS humidity_cume_dist FROM device_readings;
